'use strict';
const state={project:'',projects:[],machines:[],images:[],events:[],summary:null,caps:null,me:null,selected:null,golden:[],activeGolden:null,jobs:[],selectedJob:null,storage:null,settings:null,connectionTest:null,atlasTest:null,selectedStorageClass:'',storageRookMode:'lab',storageWipeDevice:false,storageSetupLogs:[],storageSetupPoll:null};
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
function elem(tag,cls,text){const e=document.createElement(tag);if(cls)e.className=cls;if(text!==undefined)e.textContent=String(text);return e}
function clear(e){e.replaceChildren()}
function token(){return sessionStorage.getItem('kryton.token')||''}
async function ensureAuth(){if(token())return true;try{const res=await fetch('/api/v1/lab/bootstrap',{headers:{Accept:'application/json'}});if(!res.ok)return false;const b=await res.json();if(b.autoAuth&&b.token){sessionStorage.setItem('kryton.token',b.token);return true}}catch{}return false}
async function api(path,opts={}){const run=async()=>{const headers=new Headers(opts.headers||{});headers.set('Accept','application/json');if(opts.body)headers.set('Content-Type','application/json');if(token())headers.set('Authorization','Bearer '+token());return fetch(path,{...opts,headers})};let res=await run();if(res.status===401){if(await ensureAuth())res=await run();if(res.status===401){openAuth();throw new Error('Authentication required')}}if(res.status===204)return null;let body=null;try{body=await res.json()}catch{};if(!res.ok){const err=body?.error||{};const msg=err.message||`Request failed (${res.status})`;const hint=err.hint?` — ${err.hint}`:'';const e=new Error(msg+hint);e.code=err.code;e.hint=err.hint;e.requestId=err.requestId;throw e}return body}
function toast(message){const t=$('#toast');t.textContent=message;t.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove('show'),Math.min(12000,Math.max(2800,String(message).length*40)))}
function fmtMemory(mib){if(mib>=1024)return `${Math.round(mib/102.4)/10} GB`;return `${mib} MiB`}
function ago(value){if(!value)return 'now';const s=Math.max(1,Math.floor((Date.now()-new Date(value).getTime())/1000));if(s<60)return `${s}s ago`;if(s<3600)return `${Math.floor(s/60)}m ago`;if(s<86400)return `${Math.floor(s/3600)}h ago`;return `${Math.floor(s/86400)}d ago`}
function stateClass(v){if(['failed','unknown'].includes(v))return 'failed';if(['provisioning','starting','stopping','pending'].includes(v))return 'provisioning';return v||'unknown'}
function pill(value){const p=elem('span',`state-pill ${stateClass(value)}`,value||'unknown');return p}
function setTheme(theme){document.documentElement.dataset.theme=theme;localStorage.setItem('kryton.theme',theme);const use=$('#themeIcon use');if(use)use.setAttribute('href',theme==='dark'?'#icon-sun':'#icon-moon')}
function initTheme(){const saved=localStorage.getItem('kryton.theme');setTheme(saved||(matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light'))}
function setSidebar(mode){const collapsed=mode==='collapsed';document.documentElement.dataset.sidebar=collapsed?'collapsed':'expanded';localStorage.setItem('kryton.sidebar',collapsed?'collapsed':'expanded');const btn=$('#sidebarToggle');if(btn){btn.setAttribute('aria-expanded',collapsed?'false':'true');btn.setAttribute('aria-label',collapsed?'Expand sidebar':'Collapse sidebar')}}
function icon(name,size=14){const svg=document.createElementNS('http://www.w3.org/2000/svg','svg');svg.setAttribute('class','ui-icon');svg.setAttribute('viewBox','0 0 20 20');svg.setAttribute('width',String(size));svg.setAttribute('height',String(size));svg.setAttribute('aria-hidden','true');const use=document.createElementNS('http://www.w3.org/2000/svg','use');use.setAttribute('href',`#icon-${name}`);svg.append(use);return svg}
function imageIcon(img){const wrap=elem('div','image-card-icon');wrap.append(icon(img.family==='windows-server'?'server':'desktop',16));return wrap}
function stateFilterValue(){return $('#stateFilter')?.querySelector('button.active')?.dataset.state||'all'}
function setStateFilter(value){$$('#stateFilter button').forEach(b=>b.classList.toggle('active',b.dataset.state===value))}
function updateJobsBadge(){const badge=$('#jobsNavBadge');if(!badge)return;const n=state.jobs.filter(j=>j.state==='running').length;if(n){badge.hidden=false;badge.textContent=String(n)}else badge.hidden=true}
function initSidebar(){const saved=localStorage.getItem('kryton.sidebar');const narrow=window.matchMedia('(max-width:1080px)').matches;setSidebar(!narrow&&saved==='expanded'?'expanded':'collapsed');window.matchMedia('(max-width:1080px)').addEventListener('change',e=>{if(e.matches)setSidebar('collapsed')})}
function showView(name){$$('.view').forEach(v=>v.classList.toggle('active',v.id===`view-${name}`));$$('.nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===name));if(name==='machines')renderMachines();if(name==='images'){loadImages().catch(()=>{});loadGolden().catch(()=>{});renderImages();renderGoldenPanel()}if(name==='jobs'){loadJobs().catch(()=>{});renderJobs()}if(name==='activity')renderEvents();if(name==='settings'){renderSettings();loadSettings().catch(()=>{});loadStorage().catch(()=>{})}window.scrollTo({top:0,behavior:'smooth'})}
async function bootstrap(){await ensureAuth();try{const [me,projects,images,caps]=await Promise.all([api('/api/v1/me'),api('/api/v1/projects'),api('/api/v1/images'),api('/api/v1/capabilities')]);state.me=me;state.projects=projects.items||[];state.images=images.items||[];state.caps=caps;if(!state.projects.length)throw new Error('No projects are available to this identity');state.project=state.projects.includes(localStorage.getItem('kryton.project'))?localStorage.getItem('kryton.project'):state.projects[0];populateSelectors();await Promise.all([refreshProject(),loadSettings(),loadGolden(),loadJobs(),loadStorage()]);closeAuth();startRefresh()}catch(err){if(err.message!=='Authentication required')toast(err.message)}}
function populateSelectors(){const select=$('#projectSelect'),create=$('#createProject');clear(select);clear(create);for(const p of state.projects){const a=elem('option','',p);a.value=p;select.append(a);const b=elem('option','',p);b.value=p;create.append(b)}select.value=state.project;create.value=state.project;renderImagePicker()}
function imageByID(id){return state.images.find(img=>img.id===id)}
function imageAvailability(img){return img.availability||'catalog'}
function availabilityChip(img){const a=imageAvailability(img);if(a==='stored')return{cls:'stored',label:'Stored'};if(a==='on-demand')return{cls:'ondemand',label:'Downloads on create'};return{cls:'catalog',label:'Build required'}}
function storageFoot(img){if(img.storagePath)return img.storagePath;if(img.storageNamespace&&img.storageSource==='cdi')return`CDI · ${img.storageNamespace}`;if(img.storageSource==='dockur')return'dockur/windows unattended';if(img.storageSource==='demo')return'In-memory demo';return'Not on cluster yet'}
function sortedImages(){const rank={stored:0,'on-demand':1,catalog:2};return[...state.images].sort((a,b)=>(rank[imageAvailability(a)]??9)-(rank[imageAvailability(b)]??9)||a.name.localeCompare(b.name))}
function applyImageDefaults(){const img=imageByID($('#createImage')?.value);if(!img)return;const form=$('#createForm');if(!form)return;const cpu=form.querySelector('input[name="cpu"]');const memory=form.querySelector('input[name="memory"]');const disk=form.querySelector('input[name="disk"]');if(cpu)cpu.value=Math.max(Number(cpu.value)||0,img.minCpu||4);if(memory)memory.value=Math.max(Number(memory.value)||0,img.minMemoryMiB||8192);if(disk)disk.value=Math.max(Number(disk.value)||0,img.defaultDiskGiB||80)}
function renderImageCard(img,opts={}){const selectable=!!opts.selectable,selected=!!opts.selected,compact=!!opts.compact;const card=elem('article',`image-card ${img.family==='windows-server'?'server':''}${selectable?' selectable':''}${selected?' selected':''}`);if(selectable){card.setAttribute('role','radio');card.setAttribute('aria-checked',selected?'true':'false');card.tabIndex=0;card.addEventListener('click',()=>selectImage(img.id));card.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();selectImage(img.id)}})}card.append(imageIcon(img));if(!compact)card.append(elem('div','image-card-kicker',img.family==='windows-server'?'Windows Server':'Windows Desktop'));card.append(elem('h3','',img.name),elem('div','image-card-version',img.version));if(!compact){card.append(elem('p','image-card-desc',img.description));const meta=elem('div','image-card-meta');const chip=availabilityChip(img);meta.append(elem('span',`image-chip ${chip.cls}`,chip.label));if(img.storageSource==='golden'&&img.certified)meta.append(elem('span','image-chip certified','✓ Certified'));else if(img.storageSource==='golden'&&img.availability==='stored')meta.append(elem('span','image-chip uncertified','⚠ Unverified'));for(const t of(img.tags||[]).slice(0,2))meta.append(elem('span','image-chip',t));card.append(meta)}const foot=elem('div','image-card-foot');foot.append(elem('small','',storageFoot(img)));if(!selectable&&!compact){const deploy=elem('button','text-button','Deploy');deploy.addEventListener('click',e=>{e.stopPropagation();openCreate(img.id)});foot.append(deploy)}card.append(foot);return card}
function renderImagesSection(rootId,title,desc,items){const root=$(rootId);if(!root)return;clear(root);const head=elem('div','images-section-head');const copy=elem('div');copy.append(elem('h3','',title));if(desc)copy.append(elem('p','',desc));head.append(copy);root.append(head);if(!items.length){root.append(elem('div','images-empty',`No ${title.toLowerCase()} yet.`));return}const grid=elem('div','image-showcase');for(const img of items)grid.append(renderImageCard(img));root.append(grid)}
function renderImagePicker(){const root=$('#createImagePicker'),select=$('#createImage');if(!root||!select)return;clear(root);clear(select);const items=sortedImages();const ready=items.filter(i=>i.ready);const pickFrom=ready.length?ready:items;for(const img of pickFrom){const o=elem('option','',`${img.name} · ${img.version}${img.ready?'':' (build required)'}`);o.value=img.id;select.append(o)}const preferred=items.find(i=>i.ready)?.id||pickFrom[0]?.id;if(preferred)select.value=preferred;for(const img of pickFrom){const card=renderImageCard(img,{selectable:!!img.ready||!ready.length,selected:img.id===select.value,compact:true});if(!img.ready&&ready.length){card.classList.add('disabled');card.title='Build or bootstrap this image before deploy'}root.append(card)}const hint=$('#createImageHint');if(hint){if(!ready.length&&state.caps?.provider==='kubevirt'){hint.hidden=false;hint.textContent='No CDI DataSources yet. Open Images → Golden image factory to build, or run scripts/bootstrap-kubevirt-images.sh.'}else{hint.hidden=true;hint.textContent=''}}const submit=$('#createSubmit');if(submit){submit.disabled=!canOperate()||(state.caps?.provider==='kubevirt'&&!ready.length)}}
function selectImage(id){const img=imageByID(id);if(img&&!img.ready&&state.images.some(i=>i.ready)){toast('That image is catalog-only — pick a Stored or on-demand image');return}const select=$('#createImage');if(select)select.value=id;renderImagePicker();applyImageDefaults()}
async function loadImages(){try{const res=await api('/api/v1/images');state.images=res.items||[];populateSelectors();if($('#view-images')?.classList.contains('active'))renderImages()}catch{}}
async function loadDoctor(){try{state.doctor=state.settings?.doctor||null;if(!state.doctor){const res=await fetch('/api/v1/doctor',{headers:{Accept:'application/json',...(token()?{Authorization:'Bearer '+token()}:{})}});state.doctor=await res.json()}renderDoctorBanner()}catch{state.doctor=null;renderDoctorBanner()}}
async function loadSettings(){try{state.settings=await api('/api/v1/settings');state.doctor=state.settings.doctor;renderDoctorBanner();renderConnectionSettings();renderRuntimeSettings();renderAtlasSettings();renderSettings()}catch{state.settings=null;renderConnectionSettings();renderRuntimeSettings();renderAtlasSettings()}}
function renderAtlasSettings(){const body=$('#settingsAtlasBody');if(!body)return;clear(body);const s=state.settings;if(!s){body.append(elem('p','machine-sub','Loading Atlas integration…'));return}const rt=s.runtime||{};const a=rt.atlas||{};const form=elem('form','settings-runtime-form');form.addEventListener('submit',saveAtlasSettings);const grid=elem('div','form-grid');const en=elem('label','storage-setup-check');const enBox=elem('input');enBox.type='checkbox';enBox.name='enabled';enBox.checked=!!a.enabled;en.append(enBox,elem('span','','Enable Atlas integration'));grid.append(elem('label','wide','',en));const url=elem('input');url.name='baseUrl';url.value=a.baseUrl||'';url.placeholder='http://127.0.0.1:5110';grid.append(elem('label','wide','Atlas base URL',url));const tok=elem('input');tok.name='token';tok.type='password';tok.autocomplete='off';tok.placeholder=rt.atlasTokenSet?'•••••••• (leave blank to keep)':'Bearer JWT from Atlas';grid.append(elem('label','wide','Atlas token',tok));const prod=elem('input');prod.name='product';prod.value=a.product||'kryton';prod.placeholder='kryton';grid.append(elem('label','','Owner product id',prod));const pref=elem('label','storage-setup-check');const prefBox=elem('input');prefBox.type='checkbox';prefBox.name='preferAtlas';prefBox.checked=!!a.preferAtlas;pref.append(prefBox,elem('span','','Prefer Atlas StorageClasses when choosing VM disks'));grid.append(elem('label','wide','',pref));form.append(grid);const foot=elem('div','storage-actions');if(canOperate()){const save=elem('button','primary','Save Atlas');save.type='submit';foot.append(save)}const test=elem('button','secondary','Test Atlas');test.type='button';test.addEventListener('click',()=>testAtlasConnection(form));foot.append(test);foot.append(elem('small','','Mint token: POST /api/atlas/v1/auth/tokens · subject product.service.kryton'));form.append(foot);body.append(form);if(state.atlasTest){body.append(elem('p','eyebrow','ATLAS PROBES'));const list=elem('div','settings-probe-list');for(const p of state.atlasTest.probes||[]){const row=elem('div','settings-finding-row');const copy=elem('div');copy.append(elem('strong','',p.name),elem('span','meta',`${p.message}${p.latencyMs?` · ${p.latencyMs}ms`:''}`));if(p.hint)copy.append(elem('span','meta',p.hint));row.append(probeChip(p.status),copy);list.append(row)}body.append(list);if(state.atlasTest.storageClasses?.length){body.append(elem('p','machine-sub','Classes: '+state.atlasTest.storageClasses.join(', ')))}}}
async function saveAtlasSettings(e){e.preventDefault();const form=new FormData(e.currentTarget);const atlas={enabled:form.get('enabled')==='on',baseUrl:String(form.get('baseUrl')||'').trim(),token:String(form.get('token')||'').trim(),product:String(form.get('product')||'kryton').trim()||'kryton',preferAtlas:form.get('preferAtlas')==='on'};try{state.settings=await api('/api/v1/settings',{method:'PUT',body:JSON.stringify({atlas})});toast(atlas.enabled?'Atlas integration saved':'Atlas integration disabled');renderAtlasSettings();renderSettings()}catch(err){toast(err.message)}}
async function testAtlasConnection(formEl){const form=new FormData(formEl);const body={enabled:true,baseUrl:String(form.get('baseUrl')||'').trim(),token:String(form.get('token')||'').trim(),product:String(form.get('product')||'kryton').trim()||'kryton'};try{const res=await fetch('/api/v1/integrations/atlas/test',{method:'POST',headers:{Accept:'application/json','Content-Type':'application/json',...(token()?{Authorization:'Bearer '+token()}:{})},body:JSON.stringify(body)});state.atlasTest=await res.json();renderAtlasSettings();toast(state.atlasTest.healthy?'Atlas connection OK':'Atlas connection issues')}catch(err){toast(err.message)}}
function probeChip(status){return elem('span',`storage-chip ${status==='pass'?'ok':status==='warn'?'warn':status==='fail'?'warn':''}`,status||'unknown')}
function renderFindingRow(f){const row=elem('div','settings-finding-row');const copy=elem('div');copy.append(elem('strong','',f.check),elem('span','meta',f.message));if(f.hint)copy.append(elem('span','meta',f.hint));row.append(probeChip(f.status),copy);return row}
function renderConnectionSettings(){const body=$('#settingsConnectionBody');if(!body)return;clear(body);const actions=elem('div','storage-actions');const test=elem('button','primary','Test connection');test.addEventListener('click',runConnectionTest);actions.append(test);const refresh=elem('button','secondary','Refresh');refresh.addEventListener('click',()=>loadSettings().catch(e=>toast(e.message)));actions.append(refresh);body.append(actions);const d=state.connectionTest||state.settings;if(!d){body.append(elem('p','machine-sub','Loading health checks…'));return}const summary=elem('p','machine-sub',d.healthy===false?'Some checks failed — fix before creating machines.':d.healthy===true?'All connection checks passed.':'Run a connection test to verify the control plane.');body.append(summary);if(d.connection?.probes?.length){const list=elem('div','settings-probe-list');for(const p of d.connection.probes){const row=elem('div','settings-finding-row');const copy=elem('div');copy.append(elem('strong','',p.name),elem('span','meta',`${p.message}${p.latencyMs?` · ${p.latencyMs}ms`:''}`));if(p.hint)copy.append(elem('span','meta',p.hint));row.append(probeChip(p.status),copy);list.append(row)}body.append(list)}const doc=d.doctor||state.settings?.doctor;if(doc?.findings?.length){body.append(elem('p','eyebrow','DOCTOR'));const list=elem('div','settings-finding-list');for(const f of doc.findings)list.append(renderFindingRow(f));body.append(list)}const sys=state.settings?.system;if(sys){body.append(elem('p','eyebrow','SYSTEM'));const sysdl=elem('dl','settings-readonly');renderDL(sysdl,[['Provider',sys.provider],['Auth',sys.authMode],['Kubernetes',sys.kubernetesConnected?(sys.kubernetesEndpoint||'connected'):'not connected'],['Projects',(sys.projects||[]).join(', ')],['Install scripts',sys.scriptsAvailable?'available':'not on host']]);body.append(sysdl)}}
async function runConnectionTest(ev){const btn=ev?.currentTarget;if(btn){btn.disabled=true;btn.textContent='Testing…'}try{const res=await fetch('/api/v1/settings/test',{method:'POST',headers:{Accept:'application/json',...(token()?{Authorization:'Bearer '+token()}:{})}});state.connectionTest=await res.json();state.doctor=state.connectionTest.doctor;renderDoctorBanner();renderConnectionSettings();toast(state.connectionTest.healthy?'Connection OK':'Connection issues found')}catch(err){toast(err.message)}finally{if(btn){btn.disabled=false;btn.textContent='Test connection'}}}
function renderRuntimeSettings(){const body=$('#settingsRuntimeBody');if(!body)return;clear(body);const s=state.settings;if(!s){body.append(elem('p','machine-sub','Loading operator settings…'));return}const rt=s.runtime||{},sys=s.system||{};const form=elem('form','settings-runtime-form');form.addEventListener('submit',saveRuntimeSettings);const grid=elem('div','form-grid');const proj=elem('select');proj.name='defaultProject';for(const p of sys.projects||[])proj.append(Object.assign(elem('option','',p),{value:p}));proj.value=rt.defaultProject||sys.defaultProjectEnv||'';grid.append(elem('label','','Default project',proj));if(state.caps?.provider==='kubevirt'){const ns=elem('input');ns.name='imageNamespace';ns.value=rt.imageNamespace||sys.imageNamespaceEnv||'';ns.placeholder='kryton-images';grid.append(elem('label','wide','CDI image namespace',ns))}const sc=elem('input');sc.name='storageClass';sc.value=rt.storageClass||'';sc.placeholder='rook-ceph-block';grid.append(elem('label','wide','VM storage class',sc));const hook=elem('input');hook.name='eventWebhookUrl';hook.value=rt.eventWebhookUrl||'';hook.placeholder='https://…';grid.append(elem('label','wide','Event webhook URL',hook));form.append(grid);const foot=elem('div','storage-actions');if(canOperate()){const save=elem('button','primary','Save settings');save.type='submit';foot.append(save)}foot.append(elem('small','',`Persisted under ${sys.settingsConfigFile||'~/.kryton/settings.json'}`));form.append(foot);body.append(form);body.append(elem('p','machine-sub','Restart-required (read-only): provider, auth mode, TLS, and KRYTON_PROJECTS come from the service environment.'))}
async function saveRuntimeSettings(e){e.preventDefault();const form=new FormData(e.currentTarget);const body={defaultProject:String(form.get('defaultProject')||''),storageClass:String(form.get('storageClass')||''),eventWebhookUrl:String(form.get('eventWebhookUrl')||'')};if(form.has('imageNamespace'))body.imageNamespace=String(form.get('imageNamespace')||'');try{state.settings=await api('/api/v1/settings',{method:'PUT',body:JSON.stringify(body)});state.doctor=state.settings.doctor;toast('Settings saved');await loadStorage();renderRuntimeSettings();renderConnectionSettings();renderSettings()}catch(err){toast(err.message)}}
function renderDoctorBanner(){const host=$('#doctorBanner');if(!host)return;clear(host);const d=state.doctor;if(!d||d.healthy)return;const failed=(d.findings||[]).filter(f=>f.status==='fail');const warns=(d.findings||[]).filter(f=>f.status==='warn');const lead=failed[0]||warns[0];if(!lead)return;const box=elem('article','surface doctor-banner');box.append(elem('p','eyebrow','SETUP CHECK'),elem('h3','',lead.message),elem('p','',lead.hint||'Fix the control plane before creating Windows machines from this UI.'));host.append(box)}
async function refreshProject(){const q=encodeURIComponent(state.project);const [summary,machines,events]=await Promise.all([api(`/api/v1/summary?project=${q}`),api(`/api/v1/machines?project=${q}`),api('/api/v1/events?limit=100')]);state.summary=summary;state.machines=machines.items||[];state.events=events.items||[];renderOverview();renderMachines();renderEvents();renderSettings();$('#providerSide').textContent=`${summary.provider} · ${state.project}`;loadJobs().catch(()=>{})}
function renderOverview(){const s=state.summary;if(!s)return;const health=s.machines?Math.max(0,Math.round((s.running/(s.machines||1))*100)):100;$('#metricTotal').textContent=s.machines;$('#metricRunning').textContent=s.running;$('#metricCPU').textContent=s.cpu;$('#metricMemory').textContent=fmtMemory(s.memoryMiB);$('#healthPercent').textContent=`${health}%`;$('#heroTitle').textContent=s.attention?`${s.attention} workload${s.attention===1?' needs':'s need'} attention.`:s.machines?`${s.running} machine${s.running===1?' is':'s are'} operating smoothly.`:'Your Windows estate is ready.';$('#heroSubtitle').textContent=s.machines?`${s.stopped} stopped · ${s.cpu} vCPU · ${fmtMemory(s.memoryMiB)} allocated`:'Create the first workload for this project.';renderMiniMachines($('#overviewMachines'),state.machines.slice(0,5));renderTimeline($('#overviewEvents'),state.events.slice(0,6));renderOverviewJobs()}
function renderMiniMachines(root,items){clear(root);if(!items.length){root.append(empty('No machines yet. Create the first Windows workload.'));return}for(const m of items){const row=elem('div','mini-machine');row.append(machineName(m),elem('div','resource-copy',m.spec.image),pill(m.state),elem('div','resource-copy',m.ipAddresses?.[0]||'No IP'));row.addEventListener('click',()=>openDetail(m.id));root.append(row)}}
function machineName(m){const box=elem('div');const n=elem('div','machine-title',m.spec.name);const sub=elem('div','machine-sub',m.id);box.append(n,sub);return box}
function renderMachines(){const root=$('#machineTable');if(!root)return;clear(root);const search=($('#machineSearch')?.value||'').toLowerCase(),filter=stateFilterValue();const items=state.machines.filter(m=>(filter==='all'||m.state===filter||(filter==='failed'&&['failed','unknown'].includes(m.state)))&&(!search||m.spec.name.toLowerCase().includes(search)||m.id.toLowerCase().includes(search)||m.spec.image.toLowerCase().includes(search)));if(!items.length){root.append(empty(state.machines.length?'No machines match the current filters.':'No machines yet. Create the first Windows workload.'));return}for(const m of items){const row=elem('div','machine-row');const name=elem('div','name-cell');name.append(elem('strong','',m.spec.name),elem('span','',m.id));const image=elem('div','table-copy',m.spec.image);const resources=elem('div','table-copy',`${m.spec.compute.cpu} vCPU · ${fmtMemory(m.spec.compute.memoryMiB)}`);const st=elem('div');st.append(pill(m.state));const ip=elem('div','table-copy',m.ipAddresses?.[0]||'—');const actions=elem('div','row-actions');const more=elem('button','more-button','•••');more.setAttribute('aria-label','Machine actions');more.addEventListener('click',e=>{e.stopPropagation();openDetail(m.id)});actions.append(more);row.append(name,image,resources,st,ip,actions);row.addEventListener('click',()=>openDetail(m.id));root.append(row)}}
function renderImages(){const stored=state.images.filter(i=>imageAvailability(i)==='stored');const onDemand=state.images.filter(i=>imageAvailability(i)==='on-demand');const catalog=state.images.filter(i=>imageAvailability(i)==='catalog');renderImagesSection('#imagesStoredSection','Stored on this estate','Golden images and CDI DataSources ready to deploy immediately.',stored);renderImagesSection('#imagesOnDemandSection','Ready on demand','Downloaded and installed automatically when you create a machine.',onDemand);renderImagesSection('#imagesCatalogSection','Catalog only','Available after a golden image build or CDI bootstrap.',catalog);renderGoldenPanel()}
async function loadGolden(){try{const res=await api('/api/v1/golden');state.golden=res.items||[];const active=state.golden.find(b=>!['ready','failed','idle'].includes(b.state));state.activeGolden=active||state.golden[0]||null;renderGoldenPanel();maybeGoldenPoll()}catch{state.golden=[];state.activeGolden=null;renderGoldenPanel()}}
function goldenStepIndex(build){const phase=build?.phase||'';if(['validate','complete'].includes(phase)||build?.state==='ready')return 6;if(phase==='convert')return 5;if(['generalize','sysprep'].includes(phase)||build?.state==='sysprep')return 4;if(phase==='windows_setup'||build?.state==='installing')return 3;if(phase==='download')return 2;return 1}
function renderGoldenPanel(){const host=$('#goldenPanel');if(!host)return;clear(host);const enabled=!!state.caps?.goldenImages;host.append(elem('p','eyebrow','GOLDEN IMAGE FACTORY'));const title=elem('h3','','Build KubeVirt golden images with dockur/windows');host.append(title);host.append(elem('p','','Uses the same unattended installer as dockur/windows: automatic ISO download, Windows setup, VirtIO drivers, then Kryton Sysprep capture for CDI.'));if(!enabled){host.append(elem('p','golden-meta','Golden builder needs docker and /dev/kvm on the krytond host. Run: VERSION=11e ./scripts/build-golden-image.sh --auto'));return}const build=state.activeGolden;const goldenJob=build?state.jobs.find(j=>j.kind==='golden'&&j.id===`golden:${build.id}`):null;if(goldenJob&&goldenJob.state==='running')host.append(renderJobConsole(goldenJob));const steps=elem('div','golden-steps');const labels=[['1','Start dockur'],['2','Download ISO'],['3','Install Windows'],['4','Sysprep'],['5','Capture qcow2'],['6','Validate']];const idx=build?goldenStepIndex(build):0;labels.forEach((l,i)=>{const s=elem('div',`golden-step${i+1<idx?' done':i+1===idx?' active':''}`);s.append(elem('span','',l[0]),elem('strong','',l[1]));steps.append(s)});if(!goldenJob||goldenJob.state!=='running')host.append(steps);if(build&&!goldenJob){const bar=elem('div','progress-wrap');const fill=elem('div','progress-fill');fill.style.width=Math.max(0,Math.min(100,build.progressPercent||0))+'%';bar.append(fill);host.append(bar,elem('p','golden-meta',`${build.message||''}${build.outputPath?` · ${build.outputPath}`:''}`))}if(build?.consoleUrl&&['starting','installing','sysprep'].includes(build.state)){const box=elem('div','golden-console');const head=elem('div','golden-console-head');head.append(elem('span','','dockur web viewer'),elem('a','text-button'));head.lastChild.href=build.consoleUrl;head.lastChild.target='_blank';head.lastChild.rel='noopener';head.lastChild.textContent='Open full screen';box.append(head,elem('p','golden-meta','Install viewer opens in a new tab (golden builds use a dedicated dockur port).'));host.append(box)}const actions=elem('div','golden-actions');if(canOperate()&&(!build||['ready','failed'].includes(build.state))){const start=elem('button','primary','Build golden image');start.addEventListener('click',startGoldenBuild);actions.append(start)}if(build?.consoleUrl){const open=elem('a','secondary');open.href=build.consoleUrl;open.target='_blank';open.rel='noopener';open.textContent='Watch install';actions.append(open)}if(build?.state==='ready'){host.append(elem('p',`golden-meta certify-badge ${build.certified?'ok':'warn'}`,build.certified?`✓ guestkit certified${build.validationScore!=null?` (score ${build.validationScore})`:''}`:`⚠ Not boot-certified by guestkit${build.validationScore!=null?` (score ${build.validationScore})`:' (not installed on build host)'}`));const pub=elem('button','primary','Publish to KubeVirt');pub.disabled=build.bootstrapState==='running';pub.addEventListener('click',()=>bootstrapGolden(build.id));actions.append(pub);if(build.passportPath){const pp=elem('a','secondary','View passport');pp.href=`/api/v1/golden/${encodeURIComponent(build.id)}/passport`;pp.target='_blank';pp.rel='noopener';actions.append(pp)}if(build.bootstrapState==='running')host.append(elem('p','golden-meta','Publishing to CDI… '+ (build.bootstrapMessage||'')));if(build.bootstrapState==='ready')host.append(elem('p','golden-meta','CDI DataSource ready: '+(build.dataSource||'')));if(build.bootstrapState==='failed')host.append(elem('p','golden-meta','CDI bootstrap failed: '+(build.bootstrapMessage||'')))}const refreshBtn=elem('button','secondary','Refresh');refreshBtn.addEventListener('click',()=>{loadGolden().catch(e=>toast(e.message));loadJobs().catch(()=>{})});actions.append(refreshBtn);host.append(actions)}
async function startGoldenBuild(){const imageID=$('#createImage')?.value||'windows-11-enterprise';try{const b=await api('/api/v1/golden',{method:'POST',body:JSON.stringify({imageId:imageID,auto:true})});state.activeGolden=b;toast('Golden image build started');renderGoldenPanel();maybeGoldenPoll();await loadGolden()}catch(err){toast(err.message)}}
function maybeGoldenPoll(){clearInterval(maybeGoldenPoll.timer);const b=state.activeGolden;if(!b)return;const building=!['ready','failed','idle'].includes(b.state);const publishing=b.bootstrapState==='running';if(!building&&!publishing)return;maybeGoldenPoll.timer=setInterval(()=>loadGolden().catch(()=>{}),8000)}
async function bootstrapGolden(id){try{const b=await api(`/api/v1/golden/${encodeURIComponent(id)}/bootstrap`,{method:'POST',body:'{}'});state.activeGolden=b;toast('Publishing golden image to CDI');renderGoldenPanel();maybeGoldenPoll();await loadGolden()}catch(err){toast(err.message)}}
async function loadJobs(){try{const res=await api('/api/v1/jobs');state.jobs=res.items||[];if(state.selectedJob){const j=state.jobs.find(x=>x.id===state.selectedJob.id);if(j)state.selectedJob=j}updateJobsBadge();renderJobs();renderOverviewJobs();if($('#view-jobs')?.classList.contains('active'))renderJobs();maybeJobPoll()}catch{state.jobs=[];updateJobsBadge();renderOverviewJobs()}}
function maybeJobPoll(){clearInterval(maybeJobPoll.timer);if(!state.jobs.some(j=>j.state==='running'))return;maybeJobPoll.timer=setInterval(()=>loadJobs().catch(()=>{}),5000)}
function jobStepIcon(st){if(st==='done')return '✓';if(st==='active')return '●';if(st==='failed')return '✕';return '○'}
function fmtJobTime(t){if(!t)return '';try{return new Date(t).toLocaleTimeString()}catch{return ''}}
function withConsoleHTML(url){if(!url)return '';return url.includes('format=')?url:url+(url.includes('?')?'&':'?')+'format=html'}function consoleEmbedUrl(job){if(!job?.consoleUrl)return '';if(job.consoleUrl.startsWith('/'))return withConsoleHTML(job.consoleUrl);if(job.kind==='machine'&&job.id?.startsWith('machine:')){const machineId=job.id.slice(8);const project=encodeURIComponent(job.project||state.project||'default');return withConsoleHTML(`/api/v1/machines/${encodeURIComponent(machineId)}/console/?project=${project}`)}return ''}
function consoleOpenUrl(job){return consoleEmbedUrl(job)||job?.consoleUrl||''}
function machineConsoleEmbed(m){if(!m?.consoleUrl)return '';const url=m.consoleUrl.startsWith('/')?m.consoleUrl:`/api/v1/machines/${encodeURIComponent(m.id)}/console/?project=${encodeURIComponent(m.project||state.project||'default')}`;return withConsoleHTML(url)}
function renderJobConsole(job){const box=elem('div','job-console');const chrome=elem('div','job-console-chrome');chrome.append(elem('span','job-console-title',job.name));const body=elem('div','job-console-body');const layout=elem('div','job-console-layout');const stepsCol=elem('div','job-console-steps');for(const step of job.steps||[]){const row=elem('div',`job-step ${step.state}`);row.append(elem('span','job-step-icon',jobStepIcon(step.state)));const copy=elem('div');copy.append(elem('span','job-step-label',step.label));if(step.detail)copy.append(elem('span','job-step-detail',step.detail));row.append(copy);stepsCol.append(row)}const log=elem('pre','job-console-log');for(const line of job.logs||[]){const row=elem('div',`job-log-line ${line.level||'info'}`);if(line.time)row.append(elem('span','job-log-time',fmtJobTime(line.time)));row.append(document.createTextNode(line.message||''));log.append(row)}if(!(job.logs||[]).length)log.append(elem('div','job-log-line info','Waiting for log output…'));layout.append(stepsCol,log);body.append(layout);const foot=elem('div','job-console-foot');foot.append(elem('span','',`${job.progressPercent||0}% · ${job.state}`));const openUrl=consoleOpenUrl(job);if(openUrl){const a=elem('a','text-button');a.href=openUrl;a.target='_blank';a.rel='noopener';a.textContent='Open install viewer';foot.append(a)}box.append(chrome,body,foot);return box}
function renderOverviewJobs(){const host=$('#overviewJobs');if(!host)return;clear(host);const running=state.jobs.filter(j=>j.state==='running');if(!running.length)return;const card=elem('article','surface job-card');const head=elem('div','job-card-head');head.append(elem('div'),elem('h3','',running[0].name),elem('button','text-button','View all jobs'));head.lastChild.addEventListener('click',()=>showView('jobs'));card.append(elem('p','eyebrow','ACTIVE JOB'),head,running[0].message?elem('p','golden-meta',running[0].message):elem('span'),renderJobConsole(running[0]));host.append(card)}
function renderJobs(){const root=$('#jobsList');if(!root)return;clear(root);if(!state.jobs.length){root.append(empty('No active jobs. Create a machine or start a golden image build to see live steps here.'));return}for(const job of state.jobs){const card=elem('article','surface job-card');const head=elem('div','job-card-head');head.append(elem('h3','',job.name),pill(job.state==='running'?'provisioning':job.state==='failed'?'failed':'running'));card.append(elem('p','eyebrow',job.kind.toUpperCase()+' JOB'),head,job.message?elem('p','golden-meta',job.message):elem('span'),renderJobConsole(job));const embed=consoleEmbedUrl(job);if(embed){const frameWrap=elem('div','golden-console');const frameHead=elem('div','golden-console-head');frameHead.append(elem('span','','Live install viewer'),elem('a','text-button'));frameHead.lastChild.href=consoleOpenUrl(job);frameHead.lastChild.target='_blank';frameHead.lastChild.rel='noopener';frameHead.lastChild.textContent='Full screen';const frame=elem('iframe');frame.src=embed;frame.title='Install console';frameWrap.append(frameHead,frame);card.append(frameWrap)}root.append(card)}}
function jobForMachine(m){return state.jobs.find(j=>j.kind==='machine'&&j.id===`machine:${m.id}`)}
function eventTitle(type){const bits=String(type).split('.');return bits.slice(-2).join(' ').replace(/\b\w/g,c=>c.toUpperCase())}
function renderTimeline(root,items){clear(root);if(!items.length){root.append(empty('No activity has been recorded in this instance yet.'));return}for(const e of items){const row=elem('div','timeline-item');const dot=elem('span','timeline-dot');const body=elem('div');body.append(elem('div','timeline-title',eventTitle(e.type)),elem('div','timeline-copy',eventDescription(e)));row.append(dot,body,elem('span','timeline-time',ago(e.time)));root.append(row)}}
