function renderSettings(){if(!state.me||!state.caps)return;renderDL($('#identityDetails'),[['Identity',state.me.name],['Role',state.me.role],['Projects',(state.me.projects||[]).join(', ')]]);const sc=state.storage?.config?.storageClass||'cluster default';renderDL($('#providerDetails'),[['Provider',state.caps.provider],['VM storage class',sc],['Golden images',yes(state.caps.goldenImages)],['Snapshots',yes(state.caps.snapshots)],['Networks',yes(state.caps.networks)],['TTL cleanup',yes(state.caps.ttl)],['Live migration',yes(state.caps.liveMigration)],['Console',yes(state.caps.console)]]);renderStorageSettings()}
async function loadStorage(){try{const inv=await api('/api/v1/storage');state.storage=inv;state.selectedStorageClass=inv.config?.storageClass||'';populateCreateStorage();renderStorageSettings();renderSettings();if(inv.setup?.state==='running'&&!state.storageSetupPoll){state.storageSetupPoll=setInterval(()=>loadStorage().catch(()=>{}),4000)}else if(inv.setup?.state!=='running'&&state.storageSetupPoll){clearInterval(state.storageSetupPoll);state.storageSetupPoll=null}}catch{state.storage=null;const card=$('#storageSettingsCard');if(card)card.hidden=true}}
