function renderDockurSummary(m){if(m.provider!=='dockur')return null;const d=m.spec?.dockur;if(!d)return null;const rows=[];const add=(k,v)=>{if(v!=null&&v!==''&&v!=='—')rows.push([k,String(v)])};add('Username',d.username||m.rdpUsername);add('Hostname',d.hostname);add('Language',d.language);add('Region',d.region);add('Keyboard',d.keyboard);if(d.productKey)add('Product key','•••••-•••••-•••••-•••••-•••••');add('Domain',d.domain);add('Domain OU',d.domainOu);add('Shared folder',d.sharedDir);add('OEM folder',d.oemDir);add('Post-install cmd',d.command);add('Custom ISO',d.customIso);add('Edition',d.edition);if(d.extraDisksGiB?.length)add('Extra disks',d.extraDisksGiB.map(g=>`${g} GiB`).join(', '));if(d.audio)add('Audio','Enabled');if(d.secureBoot)add('Secure boot','TPM + secure boot');if(d.autologin===false)add('Autologin','Disabled');else if(d.autologin===true)add('Autologin','Enabled');if(!rows.length)return null;const box=elem('div','detail-dockur');box.append(elem('p','eyebrow','DOCKUR OPTIONS'));const dl=elem('dl','detail-list detail-dockur-list');renderDL(dl,rows);box.append(dl);return box}
