function syncDockurCreateFields(){const box=$('#createDockurFields');if(!box)return;box.hidden=state.caps?.provider!=='dockur'}function openCreate(imageID){$('#modalBackdrop').classList.add('open');$('#modalBackdrop').setAttribute('aria-hidden','false');$('#createProject').value=state.project;if(imageID){const select=$('#createImage');if(select)select.value=imageID}renderImagePicker();populateCreateStorage();applyImageDefaults();syncDockurCreateFields();setTimeout(()=>document.querySelector('#createForm input[name="name"]').focus(),50)}
function closeCreate(){$('#modalBackdrop').classList.remove('open');$('#modalBackdrop').setAttribute('aria-hidden','true')}
async function submitCreate(e){e.preventDefault();const form=new FormData(e.currentTarget);const imageID=String(form.get('image'));const img=imageByID(imageID);if(img&&!img.ready){toast(`Image "${img.name}" is not ready. Build a golden image or bootstrap a CDI DataSource first.`);return}const body={project:String(form.get('project')),name:String(form.get('name')).trim(),image:imageID,compute:{cpu:Number(form.get('cpu')),memoryMiB:Number(form.get('memory'))},disk:{sizeGiB:Number(form.get('disk'))},network:{networkId:String(form.get('network')).trim()},ttlMinutes:Number(form.get('ttl')||0)};const sc=String(form.get('storageClass')||'').trim();if(sc)body.disk.storageClass=sc;if(state.caps?.provider==='dockur'){const dockur={username:String(form.get('dockurUsername')||'').trim(),password:String(form.get('dockurPassword')||''),hostname:String(form.get('dockurHostname')||'').trim(),language:String(form.get('dockurLanguage')||'').trim(),region:String(form.get('dockurRegion')||'').trim(),keyboard:String(form.get('dockurKeyboard')||'').trim(),productKey:String(form.get('dockurProductKey')||'').trim(),domain:String(form.get('dockurDomain')||'').trim(),domainOu:String(form.get('dockurDomainOu')||'').trim(),sharedDir:String(form.get('dockurSharedDir')||'').trim(),oemDir:String(form.get('dockurOemDir')||'').trim(),command:String(form.get('dockurCommand')||'').trim(),customIso:String(form.get('dockurCustomIso')||'').trim(),edition:String(form.get('dockurEdition')||'').trim(),audio:!!form.get('dockurAudio'),secureBoot:!!form.get('dockurSecureBoot')};if(form.get('dockurNoAutologin'))dockur.autologin=false;const extra=String(form.get('dockurExtraDisks')||'').split(',').map(s=>Number(s.trim())).filter(n=>n>0);if(extra.length)dockur.extraDisksGiB=extra;body.dockur=dockur;}const button=$('#createSubmit');button.disabled=true;button.textContent='Creating…';try{const m=await api('/api/v1/machines',{method:'POST',body:JSON.stringify(body)});state.project=body.project;localStorage.setItem('kryton.project',state.project);$('#projectSelect').value=state.project;closeCreate();toast(`${m.spec.name} is being provisioned`);await refreshProject();await loadJobs();showView('jobs');}catch(err){toast(err.message)}finally{button.disabled=false;button.textContent='Create machine'}}
async function openDetail(id){try{const m=await api(`/api/v1/machines/${encodeURIComponent(id)}?project=${encodeURIComponent(state.project)}`);state.selected=m;await loadJobs().catch(()=>{});state.selectedSnapshots=[];if(state.caps?.snapshots){try{const res=await api(`/api/v1/machines/${encodeURIComponent(id)}/snapshots?project=${encodeURIComponent(m.project||state.project)}`);state.selectedSnapshots=res.items||[]}catch{state.selectedSnapshots=[]}}renderDetail(m);$('#detailBackdrop').classList.add('open');$('#detailBackdrop').setAttribute('aria-hidden','false')}catch(err){toast(err.message)}}
function closeDetail(){$('#detailBackdrop').classList.remove('open');$('#detailBackdrop').setAttribute('aria-hidden','true');state.selected=null}
function renderDetail(m){const root=$('#detailContent');clear(root);const hero=elem('div','detail-hero');hero.append(elem('p','eyebrow','WINDOWS MACHINE'),elem('h2','detail-name',m.spec.name),pill(m.state),elem('div','detail-id',m.id));if(m.message)hero.append(elem('div','machine-sub',m.message));root.append(hero);const job=jobForMachine(m);if(job)root.append(renderJobConsole(job));else if(m.progressPercent!=null){const bar=elem('div','progress-wrap');const fill=elem('div','progress-fill');fill.style.width=Math.max(0,Math.min(100,m.progressPercent))+'%';bar.append(fill);root.append(bar,elem('div','machine-sub',m.progressPercent+'%'))}const actions=elem('div','detail-actions');if(canOperate()){const power=elem('button','secondary',m.state==='running'?'Stop':'Start');power.addEventListener('click',()=>powerAction(m));actions.append(power)}if(state.caps?.snapshots){const snap=elem('button','secondary','Snapshot');snap.addEventListener('click',()=>snapshotAction(m));actions.append(snap)}if(canOperate()){const del=elem('button','danger-button','Delete');del.addEventListener('click',()=>deleteAction(m));actions.append(del)}const consoleUrl=machineConsoleEmbed(m);if(consoleUrl){const cons=elem('a','secondary');cons.href=consoleUrl;cons.target='_blank';cons.rel='noopener';cons.textContent='Open console';actions.append(cons)}if(m.rdpHost&&m.rdpPort){const copy=elem('button','secondary','Copy RDP');copy.type='button';copy.addEventListener('click',async()=>{const user=m.rdpUsername||m.spec?.dockur?.username||'Docker';const text=`${m.rdpHost}:${m.rdpPort} (user ${user})`;try{await navigator.clipboard.writeText(text);toast('Copied '+text)}catch{toast(text)}});actions.append(copy)}root.append(actions);if(state.caps?.snapshots)root.append(renderSnapshotPanel(m,state.selectedSnapshots||[]));const grid=elem('div','detail-grid');grid.append(detailStat('vCPU',m.spec.compute.cpu),detailStat('Memory',fmtMemory(m.spec.compute.memoryMiB)),detailStat('Boot disk',`${m.spec.disk.sizeGiB} GiB`),detailStat('IP address',m.ipAddresses?.[0]||'—'));root.append(grid);const dockurBox=renderDockurSummary(m);if(dockurBox)root.append(dockurBox);if(consoleUrl&&m.state==='running'){const frameWrap=elem('div','golden-console');const frameHead=elem('div','golden-console-head');frameHead.append(elem('span','','Console'),elem('a','text-button'));frameHead.lastChild.href=consoleUrl;frameHead.lastChild.target='_blank';frameHead.lastChild.rel='noopener';frameHead.lastChild.textContent='Full screen';const frame=elem('iframe');frame.src=consoleUrl;frame.title='Windows console';frame.allow='clipboard-read; clipboard-write';frame.referrerPolicy='no-referrer';frameWrap.append(frameHead,frame);root.append(frameWrap)}else if(consoleUrl&&['provisioning','starting'].includes(m.state)){const pending=elem('div','golden-console console-pending');const head=elem('div','golden-console-head');head.append(elem('span','','Install viewer'),elem('a','text-button'));head.lastChild.href=consoleUrl;head.lastChild.target='_blank';head.lastChild.rel='noopener';head.lastChild.textContent='Open anyway';const reason=(m.conditions||[]).find(c=>c.status==='False')?.message||m.message||'The guest is still provisioning.';pending.append(head);const body=elem('div','');body.append(elem('strong','','Console not ready yet'),elem('p','',reason),elem('p','','Keyboard and clipboard controls appear after the guest is Running. Open the console then use Paste clipboard / Ctrl+Alt+Del.'));pending.append(body);root.append(pending)}const dl=elem('dl','detail-list');const rdp=m.rdpHost&&m.rdpPort?`${m.rdpHost}:${m.rdpPort}`:'—';const rdpUser=m.rdpUsername||m.spec?.dockur?.username||'—';const rows=[['Project',m.project],['Image',m.spec.image],['Provider',m.provider],['Console',consoleUrl||'—'],['RDP',rdp],['RDP user',rdpUser],['Namespace',m.providerRef?.namespace||'—'],['Provider name',m.providerRef?.name||'—'],['Network',m.spec.network?.networkId||'Default pod network'],['Created',new Date(m.createdAt).toLocaleString()],['Expires',m.expiresAt?new Date(m.expiresAt).toLocaleString():'No TTL']];renderDL(dl,rows);root.append(dl)}
function detailStat(label,value){const d=elem('div','detail-stat');d.append(elem('span','',label),elem('strong','',value));return d}
async function powerAction(m){const action=m.state==='running'?'stop':'start';try{await api(`/api/v1/machines/${encodeURIComponent(m.id)}/${action}?project=${encodeURIComponent(m.project)}`,{method:'POST'});toast(`${m.spec.name}: ${action} requested`);await refreshProject();await openDetail(m.id)}catch(err){toast(err.message)}}
async function snapshotAction(m){const name=prompt('Snapshot name (optional)','');if(name===null)return;try{await api(`/api/v1/machines/${encodeURIComponent(m.id)}/snapshot?project=${encodeURIComponent(m.project)}`,{method:'POST',body:JSON.stringify({name:name.trim()})});toast('Snapshot requested');await refreshProject();await openDetail(m.id)}catch(err){toast(err.message)}}
async function restoreSnapshotAction(m,snap){if(!confirm(`Restore ${m.spec.name} from ${snap.name}? The machine will be stopped first.`))return;try{await api(`/api/v1/machines/${encodeURIComponent(m.id)}/snapshots/${encodeURIComponent(snap.id)}/restore?project=${encodeURIComponent(m.project)}`,{method:'POST'});toast('Restore requested');await refreshProject();await openDetail(m.id)}catch(err){toast(err.message)}}
async function deleteSnapshotAction(m,snap){if(!confirm(`Delete snapshot ${snap.name}?`))return;try{await api(`/api/v1/machines/${encodeURIComponent(m.id)}/snapshots/${encodeURIComponent(snap.id)}?project=${encodeURIComponent(m.project)}`,{method:'DELETE'});toast('Snapshot deleted');await openDetail(m.id)}catch(err){toast(err.message)}}
function renderSnapshotPanel(m,items){const box=elem('div','detail-snapshots');box.append(elem('p','eyebrow','SNAPSHOTS'));if(!items.length){box.append(elem('p','machine-sub','No snapshots yet.'));return box}for(const s of items){const row=elem('div','mini-machine');row.append(elem('div','machine-title',s.name),pill(s.state),elem('div','machine-sub',s.message||ago(s.createdAt)));if(canOperate()){const actions=elem('div','row-actions');if(s.state==='ready'){const restore=elem('button','text-button','Restore');restore.addEventListener('click',e=>{e.stopPropagation();restoreSnapshotAction(m,s)});actions.append(restore)}const del=elem('button','text-button','Delete');del.addEventListener('click',e=>{e.stopPropagation();deleteSnapshotAction(m,s)});actions.append(del);row.append(actions)}box.append(row)}return box}
function startEventStream(){if(startEventStream.ac)startEventStream.ac.abort();const ac=new AbortController();startEventStream.ac=ac;const headers={Accept:'text/event-stream'};if(token())headers.Authorization='Bearer '+token();fetch('/api/v1/events/stream',{headers,signal:ac.signal}).then(async res=>{if(!res.ok||!res.body)return;const reader=res.body.getReader();const dec=new TextDecoder();let buf='';while(true){const {value,done}=await reader.read();if(done)break;buf+=dec.decode(value,{stream:true});const parts=buf.split('\n\n');buf=parts.pop();for(const part of parts){if(!part.includes('event: cloudevent'))continue;const line=part.split('\n').find(l=>l.startsWith('data: '));if(!line)continue;try{const e=JSON.parse(line.slice(6));state.events=[e,...state.events.filter(x=>x.id!==e.id)].slice(0,100);renderEvents();if($('#view-overview')?.classList.contains('active'))renderOverview();refreshProject().catch(()=>{})}catch{}}}}).catch(()=>{})}
async function deleteAction(m){if(!confirm(`Delete ${m.spec.name}? This removes the provider VM and owned resources.`))return;try{await api(`/api/v1/machines/${encodeURIComponent(m.id)}?project=${encodeURIComponent(m.project)}`,{method:'DELETE'});closeDetail();toast(`${m.spec.name} deleted`);await refreshProject()}catch(err){toast(err.message)}}
function loginDest(){const{hostname,origin,port,protocol}=window.location;return{host:hostname||'localhost',origin:origin||'',port:port||(protocol==='https:'?'443':protocol==='http:'?'80':''),protocol:(protocol||'https:').replace(':','')}}
function scrollLoginChapter(id){document.getElementById(id)?.scrollIntoView({behavior:'smooth',block:'start'})}
async function fillLoginContext(){const d=loginDest();const set=(id,v)=>{const el=$(id);if(el)el.textContent=v||'—'};set('#loginDestHost',(d.host||'localhost')+'.');set('#loginFactHost',d.host);set('#loginFactOrigin',d.origin);set('#loginNavHost',d.host);set('#loginSignHost',d.host);document.title=`Sign in · Kryton · ${d.host||'cluster'}`;try{const disc=await fetch('/api/v1',{headers:{Accept:'application/json'}}).then(r=>r.json()).catch(()=>null);set('#loginFactAuth',disc?.auth?.mode||'—');set('#loginFactProvider',disc?.provider||'—')}catch{}try{const ready=await fetch('/readyz',{headers:{Accept:'application/json'}}).then(r=>r.json()).catch(()=>null);if(ready?.provider)set('#loginFactProvider',ready.provider);set('#loginFactReady',ready?.status?`${ready.status}${ready.provider?' · '+ready.provider:''}`:'—')}catch{set('#loginFactReady','—')}}
function openAuth(){const gate=$('#authBackdrop');gate.classList.add('open');gate.setAttribute('aria-hidden','false');document.body.classList.add('login-locked');fillLoginContext();setTimeout(()=>{$('#authToken')?.focus();scrollLoginChapter('login-sign-in')},50)}
function closeAuth(){const gate=$('#authBackdrop');gate.classList.remove('open');gate.setAttribute('aria-hidden','true');document.body.classList.remove('login-locked');document.title='Kryton — Windows virtualization control plane'}
function startRefresh(){clearInterval(startRefresh.timer);startRefresh.timer=setInterval(()=>refreshProject().catch(()=>{}),15000);startEventStream()}
function wire(){$$('[data-view]').forEach(b=>b.addEventListener('click',()=>showView(b.dataset.view)));$$('[data-view-jump]').forEach(b=>b.addEventListener('click',()=>showView(b.dataset.viewJump)));$$('[data-create]').forEach(b=>b.addEventListener('click',()=>openCreate()));$$('[data-close-modal]').forEach(b=>b.addEventListener('click',closeCreate));$('#modalBackdrop').addEventListener('click',e=>{if(e.target===$('#modalBackdrop'))closeCreate()});$('#detailBackdrop').addEventListener('click',e=>{if(e.target===$('#detailBackdrop'))closeDetail()});$('#closeDetail').addEventListener('click',closeDetail);$('#createForm').addEventListener('submit',submitCreate);$('#createImage')?.addEventListener('change',applyImageDefaults);$('#projectSelect').addEventListener('change',async e=>{state.project=e.target.value;localStorage.setItem('kryton.project',state.project);$('#createProject').value=state.project;try{await refreshProject()}catch(err){toast(err.message)}});$('#machineSearch').addEventListener('input',renderMachines);$$('#stateFilter button').forEach(b=>b.addEventListener('click',()=>{setStateFilter(b.dataset.state);renderMachines()}));$('#refreshMachines').addEventListener('click',()=>refreshProject().catch(e=>toast(e.message)));$('#refreshEvents').addEventListener('click',()=>refreshProject().catch(e=>toast(e.message)));$('#refreshJobs')?.addEventListener('click',()=>loadJobs().catch(e=>toast(e.message)));$('#themeButton').addEventListener('click',()=>setTheme(document.documentElement.dataset.theme==='dark'?'light':'dark'));$('#sidebarToggle').addEventListener('click',()=>setSidebar(document.documentElement.dataset.sidebar==='collapsed'?'expanded':'collapsed'));$('#tokenButton').addEventListener('click',openAuth);$('#profileButton').addEventListener('click',()=>showView('settings'));$$('[data-login-chapter]').forEach(b=>b.addEventListener('click',e=>{e.preventDefault();scrollLoginChapter(b.getAttribute('data-login-chapter')||b.getAttribute('href')?.slice(1))}));$('#authForm').addEventListener('submit',async e=>{e.preventDefault();const tok=$('#authToken').value.trim();if(!tok)return;sessionStorage.setItem('kryton.token',tok);$('#authToken').value='';const card=$('#loginCard');try{await bootstrap();if($('#authBackdrop').classList.contains('open')){card?.classList.add('login-shake');setTimeout(()=>card?.classList.remove('login-shake'),450)}}catch{card?.classList.add('login-shake');setTimeout(()=>card?.classList.remove('login-shake'),450)}});document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeCreate();closeDetail()}})}
initTheme();initSidebar();wire();bootstrap();
